using System;

namespace LegacyTradeReconciliation.Domain
{
    /// <summary>
    /// A single trade read from <c>trades.csv</c>.
    /// </summary>
    public sealed class TradeRecord
    {
        public required string TradeId { get; init; }
        public required string Account { get; init; }
        public required string Instrument { get; init; }
        public required decimal Quantity { get; init; }
        public required DateTime SettlementDate { get; init; }
        public required string Currency { get; init; }
        public required decimal NetAmount { get; init; }
    }
}

using System;

namespace LegacyTradeReconciliation.Domain
{
    /// <summary>
    /// A custodian position read from <c>positions.csv</c>.
    /// </summary>
    public sealed class PositionRecord
    {
        public required string PositionId { get; init; }
        public required string Account { get; init; }
        public required string Instrument { get; init; }
        public required decimal Quantity { get; init; }
        public required DateTime SettlementDate { get; init; }
        public required string Currency { get; init; }
    }
}

using System;

namespace LegacyTradeReconciliation.Domain
{
    /// <summary>
    /// A settlement instruction read from <c>settlements.csv</c>.
    /// </summary>
    public sealed class SettlementRecord
    {
        public required string SettlementId { get; init; }
        public required string Account { get; init; }
        public required string Instrument { get; init; }
        public required decimal Quantity { get; init; }
        public required DateTime SettlementDate { get; init; }
        public required string Currency { get; init; }
        public required decimal CashAmount { get; init; }
    }
}

namespace LegacyTradeReconciliation.Domain
{
    /// <summary>
    /// A manual override instruction read from <c>overrides.csv</c>.
    /// </summary>
    /// <remarks>
    /// This type deliberately keeps reference identity semantics (no value equality).
    /// The reconciliation rules distinguish between two override rows that carry
    /// identical values, so structural equality would silently collapse duplicates.
    /// </remarks>
    public sealed class ManualOverrideRecord
    {
        public required string TradeId { get; init; }
        public required string Action { get; init; }
        public required string Note { get; init; }
        public required string ApprovedBy { get; init; }
    }
}

using System;

namespace LegacyTradeReconciliation.Domain
{
    /// <summary>
    /// A row of <c>matched-trades.csv</c>. Also carries the audit trail for
    /// manually overridden or suppressed breaks.
    /// </summary>
    public sealed class MatchedTradeRecord
    {
        public required string TradeId { get; init; }
        public required string Status { get; init; }
        public required string Account { get; init; }
        public required string Instrument { get; init; }
        public required decimal Quantity { get; init; }
        public required DateTime SettlementDate { get; init; }
        public required string Currency { get; init; }
        public string? PositionId { get; init; }
        public string? SettlementId { get; init; }
        public string? OverrideNote { get; init; }
    }
}

using System;

namespace LegacyTradeReconciliation.Domain
{
    /// <summary>
    /// A row of <c>break-queue.csv</c>.
    /// </summary>
    public sealed class BreakRecord
    {
        public required string TradeId { get; init; }
        public required string Account { get; init; }
        public required string Instrument { get; init; }
        public required decimal Quantity { get; init; }
        public required DateTime SettlementDate { get; init; }
        public required string Currency { get; init; }
        public required string Reasons { get; init; }
        public string? PositionId { get; init; }
        public string? SettlementId { get; init; }

        /// <summary>
        /// True only when concrete position and settlement candidates existed for the
        /// trade. Manual overrides may resolve such breaks; they may never manufacture
        /// missing counterpart records.
        /// </summary>
        public required bool CanManualOverride { get; init; }
    }
}

