using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using LegacyTradeReconciliation.Abstractions;
using LegacyTradeReconciliation.Configuration;
using LegacyTradeReconciliation.Csv;
using LegacyTradeReconciliation.Domain;

namespace LegacyTradeReconciliation.Ledger
{
    /// <summary>
    /// Append-only <c>run-ledger.csv</c> store. The ledger is what makes an
    /// exact-input rerun for the same business date a no-op.
    /// </summary>
    public sealed class CsvRunLedgerStore : IRunLedgerStore
    {
        internal const string Header = "business_date,input_signature,total_trades_read,open_break_count,matched_count";

        public bool Contains(string outputDirectory, DateTime businessDate, string inputSignature)
        {
            ArgumentNullException.ThrowIfNull(inputSignature);

            return Load(LedgerPath(outputDirectory)).Any(entry =>
                entry.BusinessDate == businessDate &&
                string.Equals(entry.InputSignature, inputSignature, StringComparison.Ordinal));
        }

        public void AppendIfMissing(string outputDirectory, RunLedgerEntry entry)
        {
            ArgumentNullException.ThrowIfNull(entry);

            string path = LedgerPath(outputDirectory);
            if (Contains(outputDirectory, entry.BusinessDate, entry.InputSignature))
            {
                return;
            }

            var lines = new List<string>(2);
            if (!File.Exists(path))
            {
                lines.Add(Header);
            }

            lines.Add(CsvFormat.Row(
                CsvFormat.Date(entry.BusinessDate),
                entry.InputSignature,
                entry.TotalTradesRead.ToString(CultureInfo.InvariantCulture),
                entry.OpenBreakCount.ToString(CultureInfo.InvariantCulture),
                entry.MatchedCount.ToString(CultureInfo.InvariantCulture)));

            File.AppendAllLines(path, lines, CsvFormat.Utf8NoBom);
        }

        public IReadOnlyList<RunLedgerEntry> Read(string outputDirectory)
        {
            return Load(LedgerPath(outputDirectory));
        }

        private static string LedgerPath(string outputDirectory)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(outputDirectory);
            return Path.Combine(outputDirectory, BatchFileNames.RunLedger);
        }

        private static List<RunLedgerEntry> Load(string ledgerPath)
        {
            if (!File.Exists(ledgerPath))
            {
                return new List<RunLedgerEntry>();
            }

            string[] lines = File.ReadAllLines(ledgerPath);
            var entries = new List<RunLedgerEntry>(Math.Max(0, lines.Length - 1));

            for (int index = 1; index < lines.Length; index++)
            {
                if (string.IsNullOrWhiteSpace(lines[index]))
                {
                    continue;
                }

                entries.Add(ParseEntry(lines[index], index + 1));
            }

            return entries;
        }

        private static RunLedgerEntry ParseEntry(string line, int lineNumber)
        {
            string[] cells = line.Split(',');
            if (cells.Length != 5)
            {
                throw new InvalidDataException(
                    $"{BatchFileNames.RunLedger} line {lineNumber.ToString(CultureInfo.InvariantCulture)} is corrupt; the run ledger must not be edited by hand.");
            }

            try
            {
                return new RunLedgerEntry
                {
                    BusinessDate = DateTime.ParseExact(cells[0], CsvFormat.DateFormat, CultureInfo.InvariantCulture),
                    InputSignature = cells[1],
                    TotalTradesRead = int.Parse(cells[2], CultureInfo.InvariantCulture),
                    OpenBreakCount = int.Parse(cells[3], CultureInfo.InvariantCulture),
                    MatchedCount = int.Parse(cells[4], CultureInfo.InvariantCulture)
                };
            }
            catch (FormatException exception)
            {
                throw new InvalidDataException(
                    $"{BatchFileNames.RunLedger} line {lineNumber.ToString(CultureInfo.InvariantCulture)} is corrupt; the run ledger must not be edited by hand.",
                    exception);
            }
        }
    }
}

using System;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using LegacyTradeReconciliation.Abstractions;
using LegacyTradeReconciliation.Csv;

namespace LegacyTradeReconciliation.Ledger
{
    /// <summary>
    /// Computes the SHA-256 content signature of a business date plus every file in
    /// the input directory. The signature is recorded in <c>run-ledger.csv</c> and is
    /// what lets the batch recognise an exact rerun.
    /// </summary>
    /// <remarks>
    /// The payload layout (and therefore the published signature value) is a
    /// behavioral contract and must not be "improved".
    /// </remarks>
    public sealed class Sha256InputSignatureCalculator : IInputSignatureCalculator
    {
        public string Calculate(DateTime businessDate, string inputDirectory)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(inputDirectory);

            if (!Directory.Exists(inputDirectory))
            {
                throw new DirectoryNotFoundException($"Input directory '{inputDirectory}' does not exist.");
            }

            var payload = new StringBuilder();
            payload.AppendLine(businessDate.ToString(CsvFormat.DateFormat, CultureInfo.InvariantCulture));

            foreach (string filePath in Directory.GetFiles(inputDirectory).OrderBy(path => path, StringComparer.OrdinalIgnoreCase))
            {
                payload.AppendLine(Path.GetFileName(filePath));
                payload.AppendLine(File.ReadAllText(filePath));
            }

            byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(payload.ToString()));
            return Convert.ToHexStringLower(hash);
        }
    }
}

using System;
using System.Globalization;
using System.IO;
using LegacyTradeReconciliation.Abstractions;
using LegacyTradeReconciliation.Configuration;
using LegacyTradeReconciliation.Csv;
using LegacyTradeReconciliation.Domain;
using LegacyTradeReconciliation.Ledger;
using LegacyTradeReconciliation.Matching;
using LegacyTradeReconciliation.Reporting;

namespace LegacyTradeReconciliation
{
    /// <summary>
    /// Orchestrates one reconciliation run: idempotency check, reconcile, publish,
    /// then record the run in the ledger.
    /// </summary>
    public sealed class ReconciliationBatch
    {
        private readonly IReconciliationInputReader _inputReader;
        private readonly IMatchingEngine _matchingEngine;
        private readonly IEndOfDayReportBuilder _reporter;
        private readonly IReconciliationOutputWriter _outputWriter;
        private readonly IRunLedgerStore _ledgerStore;
        private readonly IInputSignatureCalculator _signatureCalculator;
        private readonly IBatchLog _log;

        /// <summary>
        /// Builds a batch wired with the production file-system collaborators.
        /// </summary>
        public static ReconciliationBatch CreateDefault(IBatchLog? log = null)
        {
            return new ReconciliationBatch(
                new CsvInputReader(),
                new MatchingEngine(),
                new EndOfDayReporter(),
                new CsvOutputWriter(),
                new CsvRunLedgerStore(),
                new Sha256InputSignatureCalculator(),
                log ?? NullBatchLog.Instance);
        }

        public ReconciliationBatch(
            IReconciliationInputReader inputReader,
            IMatchingEngine matchingEngine,
            IEndOfDayReportBuilder reporter,
            IReconciliationOutputWriter outputWriter,
            IRunLedgerStore ledgerStore,
            IInputSignatureCalculator signatureCalculator,
            IBatchLog log)
        {
            ArgumentNullException.ThrowIfNull(inputReader);
            ArgumentNullException.ThrowIfNull(matchingEngine);
            ArgumentNullException.ThrowIfNull(reporter);
            ArgumentNullException.ThrowIfNull(outputWriter);
            ArgumentNullException.ThrowIfNull(ledgerStore);
            ArgumentNullException.ThrowIfNull(signatureCalculator);
            ArgumentNullException.ThrowIfNull(log);

            _inputReader = inputReader;
            _matchingEngine = matchingEngine;
            _reporter = reporter;
            _outputWriter = outputWriter;
            _ledgerStore = ledgerStore;
            _signatureCalculator = signatureCalculator;
            _log = log;
        }

        public BatchRunOutcome Run(RunRequest request)
        {
            ArgumentNullException.ThrowIfNull(request);

            Directory.CreateDirectory(request.OutputDirectory);

            string inputSignature = _signatureCalculator.Calculate(request.BusinessDate, request.InputDirectory);

            // An exact rerun for the same business date must not republish or duplicate
            // anything, including ledger entries.
            if (_ledgerStore.Contains(request.OutputDirectory, request.BusinessDate, inputSignature) &&
                _outputWriter.OutputsExist(request.OutputDirectory))
            {
                _log.Info("Exact rerun detected for " + request.FormattedBusinessDate + ". Existing outputs were retained.");
                return BatchRunOutcome.Rerun(inputSignature);
            }

            ReconciliationInputSet inputs = _inputReader.Read(request.InputDirectory);
            ReconciliationResult result = _matchingEngine.Reconcile(inputs);

            _outputWriter.WriteMatchedTrades(request.OutputDirectory, result.MatchedTrades);
            _outputWriter.WriteBreakQueue(request.OutputDirectory, result.OpenBreaks);
            _outputWriter.WriteEndOfDayReport(request.OutputDirectory, _reporter.BuildReport(request.BusinessDate, result));

            _ledgerStore.AppendIfMissing(request.OutputDirectory, new RunLedgerEntry
            {
                BusinessDate = request.BusinessDate,
                InputSignature = inputSignature,
                TotalTradesRead = result.TotalTradesRead,
                OpenBreakCount = result.OpenBreaks.Count,
                MatchedCount = result.MatchedTrades.Count
            });

            _log.Info(string.Format(
                CultureInfo.InvariantCulture,
                "Processed {0} trades into {1} matched rows and {2} open breaks.",
                result.TotalTradesRead,
                result.MatchedTrades.Count,
                result.OpenBreaks.Count));

            return BatchRunOutcome.Published(inputSignature, result);
        }
    }

    /// <summary>
    /// What a run did, so callers and tests can assert on it without re-reading files.
    /// </summary>
    public sealed class BatchRunOutcome
    {
        private BatchRunOutcome(bool wasRerun, string inputSignature, ReconciliationResult? result)
        {
            WasRerun = wasRerun;
            InputSignature = inputSignature;
            Result = result;
        }

        /// <summary>True when the run was recognised as an exact rerun and skipped.</summary>
        public bool WasRerun { get; }

        public string InputSignature { get; }

        /// <summary>The reconciliation result, or <c>null</c> for a skipped rerun.</summary>
        public ReconciliationResult? Result { get; }

