using System;
using System.IO;
using LegacyTradeReconciliation.Configuration;

namespace LegacyTradeReconciliation.Cli
{
    /// <summary>
    /// Parses the batch command line. The accepted shapes are unchanged:
    /// no arguments (built-in sample run) or
    /// <c>&lt;business-date yyyy-MM-dd&gt; &lt;input-directory&gt; &lt;output-directory&gt;</c>.
    /// </summary>
    public static class CommandLine
    {
        public const string Usage =
            "Usage: LegacyTradeReconciliation [<business-date yyyy-MM-dd> <input-directory> <output-directory>]";

        public static RunRequest Parse(string[]? args, string baseDirectory)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(baseDirectory);

            if (args is null || args.Length == 0)
            {
                return new RunRequest(
                    new DateTime(2025, 3, 17),
                    Path.Combine(baseDirectory, "data", "sample"),
                    Path.Combine(baseDirectory, "output", "sample"));
            }

            if (args.Length != 3)
            {
                throw new ArgumentException(
                    "Expected either no arguments or: <business-date yyyy-MM-dd> <input-directory> <output-directory>.",
                    nameof(args));
            }

            return new RunRequest(
                RunRequest.ParseBusinessDate(args[0]),
                args[1],
                args[2]);
        }
    }
}

using System;
using LegacyTradeReconciliation.Abstractions;

namespace LegacyTradeReconciliation.Cli
{
    /// <summary>
    /// Writes operational progress to standard output. Diagnostics that describe a
    /// failure go to standard error so batch schedulers can separate them.
    /// </summary>
    internal sealed class ConsoleBatchLog : IBatchLog
    {
        public void Info(string message)
        {
            Console.Out.WriteLine(message);
        }

        public static void Error(string message)
        {
            Console.Error.WriteLine(message);
        }
    }
}

using System;
using System.IO;
using System.Security;
using LegacyTradeReconciliation.Configuration;

namespace LegacyTradeReconciliation.Cli
{
    /// <summary>
    /// Entry point for the reconciliation batch.
    /// </summary>
    public static class Program
    {
        /// <summary>Reconciliation completed, or an exact rerun was skipped.</summary>
        public const int ExitSuccess = 0;

        /// <summary>The command line or the business date could not be understood.</summary>
        public const int ExitInvalidArguments = 2;

        /// <summary>Input data or the environment prevented the batch from running.</summary>
        public const int ExitRunFailed = 3;

        public static int Main(string[] args)
        {
            var log = new ConsoleBatchLog();

            RunRequest request;
            try
            {
                request = CommandLine.Parse(args, AppContext.BaseDirectory);
            }
            catch (Exception exception) when (exception is ArgumentException or FormatException)
            {
                ConsoleBatchLog.Error(exception.Message);
                ConsoleBatchLog.Error(CommandLine.Usage);
                return ExitInvalidArguments;
            }

            try
            {
                ReconciliationBatch.CreateDefault(log).Run(request);
                return ExitSuccess;
            }
            catch (Exception exception) when (
                exception is IOException or
                UnauthorizedAccessException or
                SecurityException or
                FormatException or
                OverflowException or
                NotSupportedException)
            {
                // Operability: batch schedulers get a single actionable line on stderr
                // and a distinct exit code instead of an unhandled stack trace.
                ConsoleBatchLog.Error("Reconciliation run failed: " + exception.Message);
                return ExitRunFailed;
            }
        }
    }
}

