using System;
using System.IO;
using LegacyTradeReconciliation.Configuration;
using LegacyTradeReconciliation.Ledger;
using Xunit;

namespace LegacyTradeReconciliation.Tests
{
    public sealed class InputSignatureTests
    {
        private readonly Sha256InputSignatureCalculator _calculator = new();

        /// <summary>
        /// The signature is published in <c>run-ledger.csv</c>, so these are the exact
        /// values the .NET Framework batch produced for the shipped fixtures.
        /// </summary>
        [Theory]
        [InlineData("baseline", "993d5b30312e3dbe1e13840e3d1ddeb76fb5359c1f964ef525595bf721f6685f")]
        [InlineData("override-rerun", "c5d01c66c9e4af13353b6d368ba9fa0e1d48dbba072302d9ed9ce5f8eebd0b7f")]
        public void Signature_matches_the_legacy_value(string scenario, string expected)
        {
            if (!string.Equals(Environment.NewLine, "\r\n", StringComparison.Ordinal))
            {
                // The legacy payload separator is the platform newline; the pinned
                // values were produced on Windows.
                return;
            }

            Assert.Equal(expected, _calculator.Calculate(new DateTime(2025, 3, 17), TestEnvironment.FixtureInput(scenario)));
        }

        [Fact]
        public void Signature_is_stable_across_calls()
        {
            string input = TestEnvironment.FixtureInput("baseline");

            Assert.Equal(
                _calculator.Calculate(new DateTime(2025, 3, 17), input),
                _calculator.Calculate(new DateTime(2025, 3, 17), input));
        }

        [Fact]
        public void Signature_covers_the_business_date()
        {
            string input = TestEnvironment.FixtureInput("baseline");

            Assert.NotEqual(
                _calculator.Calculate(new DateTime(2025, 3, 17), input),
                _calculator.Calculate(new DateTime(2025, 3, 18), input));
        }

        [Fact]
        public void Signature_covers_every_file_in_the_input_directory()
        {
            using var input = new TempDirectory("signature-input");
            foreach (string file in Directory.GetFiles(TestEnvironment.FixtureInput("baseline")))
            {
                File.Copy(file, Path.Combine(input.Path, Path.GetFileName(file)), overwrite: true);
            }

            string before = _calculator.Calculate(new DateTime(2025, 3, 17), input.Path);
            File.AppendAllText(Path.Combine(input.Path, BatchFileNames.Positions), "P-9,ACC-9,BP.L,10,2025-03-17,GBP\n");
            string after = _calculator.Calculate(new DateTime(2025, 3, 17), input.Path);

            Assert.NotEqual(before, after);
        }

        [Fact]
        public void A_missing_input_directory_is_reported_clearly()
        {
            Assert.Throws<DirectoryNotFoundException>(
                () => _calculator.Calculate(new DateTime(2025, 3, 17), Path.Combine(Path.GetTempPath(), "missing-" + Guid.NewGuid().ToString("N"))));
        }
    }
}

using System;
using System.IO;
using LegacyTradeReconciliation.Configuration;
using LegacyTradeReconciliation.Domain;
using LegacyTradeReconciliation.Ledger;
using Xunit;

namespace LegacyTradeReconciliation.Tests
{
    public sealed class RunLedgerStoreTests
    {
        private static readonly DateTime BusinessDate = new(2025, 3, 17);
        private readonly CsvRunLedgerStore _store = new();

        [Fact]
        public void An_empty_ledger_contains_nothing()
        {
            using var output = new TempDirectory("ledger-empty");

            Assert.False(_store.Contains(output.Path, BusinessDate, "signature"));
            Assert.Empty(_store.Read(output.Path));
        }

        [Fact]
        public void The_header_is_written_once_and_entries_are_appended()
        {
            using var output = new TempDirectory("ledger-append");

            _store.AppendIfMissing(output.Path, Entry("signature-a", matchedCount: 2));
            _store.AppendIfMissing(output.Path, Entry("signature-b", matchedCount: 3));

            string[] lines = File.ReadAllLines(Path.Combine(output.Path, BatchFileNames.RunLedger));

            Assert.Equal("business_date,input_signature,total_trades_read,open_break_count,matched_count", lines[0]);
            Assert.Equal("2025-03-17,signature-a,5,1,2", lines[1]);
            Assert.Equal("2025-03-17,signature-b,5,1,3", lines[2]);
            Assert.Equal(3, lines.Length);
        }

        [Fact]
        public void An_identical_entry_is_never_appended_twice()
        {
            using var output = new TempDirectory("ledger-idempotent");

            _store.AppendIfMissing(output.Path, Entry("signature-a"));
            _store.AppendIfMissing(output.Path, Entry("signature-a"));

            Assert.Single(_store.Read(output.Path));
            Assert.True(_store.Contains(output.Path, BusinessDate, "signature-a"));
            Assert.False(_store.Contains(output.Path, BusinessDate.AddDays(1), "signature-a"));
        }

        [Fact]
        public void A_hand_edited_ledger_fails_loudly()
        {
            using var output = new TempDirectory("ledger-corrupt");
            File.WriteAllText(
                Path.Combine(output.Path, BatchFileNames.RunLedger),
                "business_date,input_signature,total_trades_read,open_break_count,matched_count" + Environment.NewLine +
                "2025-03-17,signature" + Environment.NewLine);

            InvalidDataException exception = Assert.Throws<InvalidDataException>(() => _store.Read(output.Path));
            Assert.Contains(BatchFileNames.RunLedger, exception.Message, StringComparison.Ordinal);
        }

        private static RunLedgerEntry Entry(string signature, int matchedCount = 2) => new()
        {
            BusinessDate = BusinessDate,
            InputSignature = signature,
            TotalTradesRead = 5,
            OpenBreakCount = 1,
            MatchedCount = matchedCount
        };
    }
}

using System;
using System.Collections.Generic;
using LegacyTradeReconciliation.Domain;
using LegacyTradeReconciliation.Reporting;
using Xunit;

namespace LegacyTradeReconciliation.Tests
{
    public sealed class EndOfDayReporterTests
    {
        private static readonly DateTime BusinessDate = new(2025, 3, 17);
        private readonly EndOfDayReporter _reporter = new();

        [Fact]
        public void A_clean_day_reports_no_break_reasons()
        {
            string report = _reporter.BuildReport(BusinessDate, Result());

            Assert.Contains("Business Date: 2025-03-17", report, StringComparison.Ordinal);
            Assert.Contains("Open Break Reasons" + Environment.NewLine + "------------------" + Environment.NewLine + "None", report, StringComparison.Ordinal);
            Assert.DoesNotContain("Stale Overrides" + Environment.NewLine + "---------------", report, StringComparison.Ordinal);
        }

        [Fact]
        public void Break_reasons_are_counted_per_component_and_sorted()
        {
            string report = _reporter.BuildReport(BusinessDate, Result(openBreaks: new[]
            {
                Break("T-2", "SettlementDateMismatch|MissingPosition"),
                Break("T-1", "MissingPosition")
            }));

            int missingPosition = report.IndexOf("MissingPosition: 2", StringComparison.Ordinal);
            int settlementDateMismatch = report.IndexOf("SettlementDateMismatch: 1", StringComparison.Ordinal);

            Assert.True(missingPosition >= 0);
            Assert.True(settlementDateMismatch > missingPosition);
        }

        [Fact]
        public void Stale_overrides_are_listed_for_audit()
        {
            string report = _reporter.BuildReport(BusinessDate, Result(staleOverrides: new[]
            {
                new ManualOverrideRecord { TradeId = "T-9", Action = "ForceMatch", Note = "n", ApprovedBy = "ops-manager" },
                new ManualOverrideRecord { TradeId = "T-1", Action = "SuppressBreak", Note = "n", ApprovedBy = "ops-supervisor" }
            }));

            Assert.Contains("Stale Overrides: 2", report, StringComparison.Ordinal);
            int first = report.IndexOf("T-1: SuppressBreak (ops-supervisor)", StringComparison.Ordinal);
            int second = report.IndexOf("T-9: ForceMatch (ops-manager)", StringComparison.Ordinal);
            Assert.True(first >= 0);
            Assert.True(second > first);
        }

        [Fact]
        public void The_report_ends_with_exactly_one_newline()
        {
            string report = _reporter.BuildReport(BusinessDate, Result());

            Assert.EndsWith("None" + Environment.NewLine, report, StringComparison.Ordinal);
        }

        private static ReconciliationResult Result(
            IReadOnlyList<BreakRecord>? openBreaks = null,
            IReadOnlyList<ManualOverrideRecord>? staleOverrides = null)
        {
            return new ReconciliationResult
            {
                MatchedTrades = Array.Empty<MatchedTradeRecord>(),
                OpenBreaks = openBreaks ?? Array.Empty<BreakRecord>(),
                StaleOverrides = staleOverrides ?? Array.Empty<ManualOverrideRecord>(),
                TotalTradesRead = 0,
                CanonicalTradeCount = 0,
                DuplicateTradeCount = 0,
                MatchedCount = 0,
                ManualOverrideMatchedCount = 0,
                ManualOverrideSuppressedCount = 0
            };
        }

        private static BreakRecord Break(string tradeId, string reasons) => new()
        {
            TradeId = tradeId,
            Account = "ACC-001",
            Instrument = "IBM.N",
            Quantity = 100m,
            SettlementDate = BusinessDate,
            Currency = "USD",
            Reasons = reasons,
            CanManualOverride = false
        };
    }
}

